#!/usr/bin/env python3
import os
import re
import sys
from time import sleep

from auto_config.generate_config import generator  # type: ignore
from ta_emss import ta_emss
from taf.gnb.oam.coam.cu import cu

# INPUT PARAMETERS
BUILD = "vCUCNF25R2_0.250.28098"
OUTPUT_DIR = "/home/ute/config_out"
CUSTOM_DIR = "/home/ute/auto_config/test/yamls/"
YAML_MAP = "epc=epc.yaml,bts=veryfast-vcu-100-vdu-1600-cell.yaml"

# DYNAMIC LINKS PARAMS
SIM_VDU_ID_START = None
CELL_ID_START = None
AMF_ID_START = 1


def autosetup_links():

    emss1 = ta_emss()
    emss1.setup_emss(bts_id=1, user="vcu1", bts_ip="192.168.100.129", oam_ip="192.168.100.1/24", alias="cu1")
    emss1.xterm_setup(
        # --- XNAP PARAMS ---
        gnbsim_eth_if="eth3",
        gnbsim_ip_addr_mask=24,
        # --- F1AP PARAMS ---
        vdusim_eth_if="eth3",
        vdusim_ip_addr_mask=24,
        init_vdu_gnb_du_id=SIM_VDU_ID_START,
        init_vdu_cell_id_begin=CELL_ID_START,
        # --- NGAP PARAMS ---
        amf_eth_if="eth3",
        amf_ip_addr_mask="24",
        amf_id_start=AMF_ID_START,
        # --- XTERM OPTIONS ---
        verbose=True,
        debug=False,
        # --- Auto Setup ---
        dynamic_setup=True,
    )

    emss1.xterm_autostart()

    # --- BREAK SIMULATION ---
    while input("Press 'q' to stop...") != "q":
        pass

    emss1.xterm_teardown()


def generate_scfc():
    generator.generate_scfc(
        enb_id="1=1",
        build=BUILD,
        custom_dir=CUSTOM_DIR,
        yaml_map=YAML_MAP,
        output_dir=OUTPUT_DIR,
    )


def perform_commissioning():

    def create_cuoam_string(build):
        match = re.search(r"\d\dR\d", build)

        if match:
            version_substring = match.group(0)
            version_substring_lower = version_substring.lower()
            return f"cuoam_{version_substring_lower}"

        sys.exit(f"Cannot obtain 'coam' string from {build=}")

    cu_object = cu()
    coam_version = create_cuoam_string(BUILD)
    cu_object.connect_to(
        host="192.168.100.129",
        port="443",
        username="Nemuadmin",
        password="Nokia@123",
        cu_version=coam_version,
        secure=True,
    )

    release = BUILD.split("_")[0]
    scf_candidates = list(filter(lambda p: release in p and p.endswith(".xml"), os.listdir(OUTPUT_DIR)))
    if len(scf_candidates) == 0:
        print(f"No .xml file was found under {OUTPUT_DIR} directory.")

    if len(scf_candidates) > 1:
        print(f"Multiple .xml file was found under {OUTPUT_DIR} directory.")

    scf_file = os.path.join(OUTPUT_DIR, scf_candidates[0])
    print(f"Commissioning file {scf_file=}")
    cu_object.perform_commissioning(scf_file=scf_file)

    def verify_cplane_addresses(cu_response):
        ip_addresses = cu_response.get("ip_addresses", {})

        f1_cplane_available = ip_addresses.get("f1_interface", {}).get("c_plane_ip_address") is not None
        ng_cplane_available = ip_addresses.get("ng_interface", {}).get("c_plane_ip_address") is not None
        xn_cplane_available = ip_addresses.get("xn_interface", {}).get("c_plane_ip_address") is not None

        return f1_cplane_available and ng_cplane_available and xn_cplane_available

    for i in range(1, 11):
        print(f"Try: {i} of waiting for reboot to be completed.")
        try:
            cu_response = cu_object.get_cu_state()
            if verify_cplane_addresses(cu_response):
                break
        except Exception:
            pass
        finally:
            sleep(20)
    else:
        print("VCU Commissioning unsuccessful. Quitting...")
        sys.exit(1)


if __name__ == "__main__":
    generate_scfc()
    perform_commissioning()
    autosetup_links()
